<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes;
class Project extends Model {use SoftDeletes;protected $guarded=[];protected function casts():array{return ['is_featured'=>'boolean','published_at'=>'datetime','open_sale_date'=>'date','completion_date'=>'date'];} public function translations(){return $this->hasMany(ProjectTranslation::class);} public function translation(?string $locale=null){return $this->translations->firstWhere('locale',$locale?:app()->getLocale())??$this->translations->firstWhere('locale',config('app.fallback_locale'))??$this->translations->first();} public function amenities(){return $this->belongsToMany(Amenity::class,'project_amenity');} public function units(){return $this->hasMany(ProjectUnit::class);} public function location(){return $this->belongsTo(Location::class);} public function properties(){return $this->hasMany(Property::class);}}
